insert into public.thesis_framework_categories(key,version,label,definition,origin,status,inclusion,exclusion,change_reason) values('monitoring',1,'Monitoreo','Reconoce cómo avanza su comprensión y detecta discrepancias entre lo esperado y lo observado.','deductive','active','Exigir evidencia textual y contexto; interpretar según el episodio completo.','No inferir procesos psicológicos a partir de clics o frecuencia por sí solos.','Marco inicial derivado de la metodología suministrada; sujeto a revisión del equipo.') on conflict(key,version) do nothing;
